<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';const route=useRoute();const project=ref<any>({});const apps=ref<any[]>([]);const name=ref(''),description=ref(''),appName=ref('');const load=async()=>{const id=route.params.id;const [p,a]=await Promise.all([fetch(`/api/v1/projects/${id}`),fetch(`/api/v1/projects/${id}/applications`)]);if(p.ok){project.value=await p.json();description.value=project.value.description||''}if(a.ok)apps.value=await a.json()};const saveProject=async()=>{await fetch(`/api/v1/projects/${route.params.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.value,description:description.value})});name.value='';await load()};const create=async()=>{if(!appName.value.trim())return;await fetch(`/api/v1/projects/${route.params.id}/applications`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:appName.value,source_type:'compose'})});appName.value='';await load()};const saveApp=async(app:any)=>{await fetch(`/api/v1/applications/${app.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:app.name,status:app.status})});await load()};onMounted(load)</script>
<template><div class="hero"><div><p class="kicker">PROJECT / {{project.slug}}</p><h1>{{project.name}}</h1><p class="muted">{{project.description||'Organize applications for this environment.'}}</p></div><span class="pill">{{project.status}}</span></div><form class="inline-form" @submit.prevent="saveProject"><input v-model="name" placeholder="Rename project" aria-label="Rename project" /><input v-model="description" placeholder="Description" aria-label="Description" /><button class="secondary">Save project</button></form><form class="inline-form" @submit.prevent="create"><input v-model="appName" placeholder="Application name" aria-label="Application name" /><button class="primary">Add application</button></form><div v-if="apps.length" class="project-list"><article v-for="app in apps" :key="app.id"><input v-model="app.name" :aria-label="`Application ${app.name}`" /><span class="pill">{{app.status}}</span><p class="muted">{{app.source_type}} · deploy will be configured later</p><button class="secondary" @click="saveApp(app)">Save application</button></article></div><div v-else class="empty"><h2>No applications yet</h2><p>Applications are organizational records until deployment is configured.</p></div></template>
